package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"os"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

var (
	upgrader = websocket.Upgrader{
		CheckOrigin: func(r *http.Request) bool { return true },
	}
	authSecret = os.Getenv("AUTH_HMAC_SECRET")
	// Cache authenticated sessions to disk for restart recovery
	sessionCachePath = "/var/cache/sessions/active.json"
	activeSessions   = &sync.Map{}
)

type AuthMessage struct {
	UserID    string `json:"user_id"`
	Timestamp int64  `json:"timestamp"`
	Signature string `json:"signature"`
}

// validateSignature checks HMAC signature - vulnerable to timing attack
// because it uses byte-by-byte comparison via string equality
func validateSignature(userID string, timestamp int64, providedSig string) bool {
	mac := hmac.New(sha256.New, []byte(authSecret))
	mac.Write([]byte(fmt.Sprintf("%s:%d", userID, timestamp)))
	expectedSig := hex.EncodeToString(mac.Sum(nil))

	// VULNERABLE: string comparison leaks timing information
	// Each matching byte adds ~2-5ns of processing time
	return expectedSig == providedSig
}

func persistSession(userID string) error {
	// Attempt to write session to disk cache for crash recovery
	f, err := os.OpenFile(sessionCachePath, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		// If filesystem is read-only, silently skip persistence
		log.Printf("WARN: cannot persist session for %s: %v", userID, err)
		return err
	}
	defer f.Close()
	_, err = f.WriteString(fmt.Sprintf("{\"user_id\":\"%s\",\"ts\":%d}\n", userID, time.Now().Unix()))
	return err
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	// First message must be auth
	var auth AuthMessage
	err = conn.ReadJSON(&auth)
	if err != nil {
		conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"invalid auth format"}`))
		return
	}

	// Check timestamp freshness (5 minute window)
	now := time.Now().Unix()
	if now-auth.Timestamp > 300 || auth.Timestamp-now > 30 {
		conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"expired"}`))
		return
	}

	start := time.Now()
	valid := validateSignature(auth.UserID, auth.Timestamp, auth.Signature)
	elapsed := time.Since(start)

	if !valid {
		// Timing information leaks through response time
		conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"unauthorized"}`))
		log.Printf("AUTH FAILED user=%s elapsed=%v", auth.UserID, elapsed)
		return
	}

	// Persist session for recovery
	persistSession(auth.UserID)
	activeSessions.Store(auth.UserID, time.Now())

	conn.WriteMessage(websocket.TextMessage, []byte(`{"status":"authenticated"}`))

	// Main message loop
	for {
		_, msg, err := conn.ReadMessage()
		if err != nil {
			break
		}
		// Echo service for demonstration
		conn.WriteMessage(websocket.TextMessage, msg)
	}

	activeSessions.Delete(auth.UserID)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"ok"}`))
}

func main() {
	if authSecret == "" {
		log.Fatal("AUTH_HMAC_SECRET environment variable required")
	}

	http.HandleFunc("/ws", handleWebSocket)
	http.HandleFunc("/health", healthHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	log.Printf("WebSocket auth service starting on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
